/// A pattern of the grammar.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
#[repr(u16)]
pub(crate) enum Pat {
    /// The begin `(<)([-.\w]+)`.
    JsxTag,
    /// The end `(/?>)`.
    JsxTagEnd,
    /// The match `(?:^|\s+)([-.\w]+)\s*(=)`.
    JsxAttribute,
    /// The begin `"`.
    DoubleString,
    /// The end `"`.
    DoubleStringEnd,
    /// The match `…`.
    DoubleEscape,
    /// The begin `#\{`.
    Interpolation,
    /// The end `}`.
    InterpolationEnd,
    /// The begin `(</)([-.\w]+)`.
    JsxEndTag,
    /// The end `(/?>)`.
    JsxEndTagEnd,
    /// The match `(new)\s+(?:(class)\s+(\w+(?:\.\w*)*)?|(\w+(?:\.\w*)*))`.
    NewInstance,
    /// The begin `'''`.
    SingleHeredoc,
    /// The end `'''`.
    SingleHeredocEnd,
    /// The match `(\\).`.
    SingleHeredocEscape,
    /// The begin `"""`.
    DoubleHeredoc,
    /// The end `"""`.
    DoubleHeredocEnd,
    /// The match `(\\).`.
    DoubleHeredocEscape,
    /// The match `(')(.*)(')`.
    Script,
    /// The begin `(?<!#)###(?!#)`.
    BlockComment,
    /// The end `###`.
    BlockCommentEnd,
    /// The match `(?<=^|\s)@\w*(?=\s)`.
    Annotation,
    /// The begin `#`.
    LineComment,
    /// The end `$`.
    LineCommentEnd,
    /// The begin `///`.
    Heregex,
    /// The end `(///)[gimuy]*`.
    HeregexEnd,
    /// The match `\\[Bb]|[$^]`.
    Anchor,
    /// The match `\\[1-9]\d*`.
    BackReference,
    /// The match `[*+?]|\{(\d+,\d+|\d+,|,\d+|\d+)}\??`.
    Quantifier,
    /// The match `\|`.
    Or,
    /// The begin `(\()((\?=)|(\?!))`.
    Assertion,
    /// The end `(\))`.
    AssertionEnd,
    /// The begin `\((\?:)?`.
    Group,
    /// The end `\)`.
    GroupEnd,
    /// The begin `(\[)(\^)?`.
    CharacterSet,
    /// The end `(])`.
    CharacterSetEnd,
    /// The match `…`.
    CharacterRange,
    /// The match `\\[DSWdsw]|\.`.
    CharacterClass,
    /// The match `\\([0-7]{3}|x\h{2}|u\h{4})`.
    NumericEscape,
    /// The match `\\c[A-Z]`.
    ControlEscape,
    /// The match `\\.`.
    BackslashEscape,
    /// The match `(?<!\\)(#).*$\n?`.
    EmbeddedComment,
    /// The match `…`.
    KeywordControl,
    /// The match `\b(?<![$.])(delete)(?!\s*:)\b`.
    Delete,
    /// The match `\b(?<![$.])(instanceof)(?!\s*:)\b`.
    Instanceof,
    /// The match `\b(?<![$.])(new)(?!\s*:)\b`.
    New,
    /// The match `\b(?<![$.])(typeof)(?!\s*:)\b`.
    Typeof,
    /// The match `…`.
    Reserved,
    /// The begin `…`.
    FunctionAssignment,
    /// The end `[-=]>`.
    FunctionAssignmentEnd,
    /// The begin `\(`.
    Params,
    /// The end `\)`.
    ParamsEnd,
    /// The match `([$A-Z_a-z][$\w]*)(\.\.\.)?`.
    Param,
    /// The match `(@(?:[$A-Z_a-z][$\w]*)?)(\.\.\.)?`.
    InstanceParam,
    /// The begin `…`.
    QuotedFunctionAssignment,
    /// The end `[-=]>`.
    QuotedFunctionAssignmentEnd,
    /// The begin `(?=(\([^()]*\)\s*)?[-=]>)`.
    InlineFunction,
    /// The end `[-=]>`.
    InlineFunctionEnd,
    /// The begin `(?<=\s|^)(\{)(?=[^"#']+?}[]}\s]*=)`.
    DestructuredObject,
    /// The end `}`.
    DestructuredObjectEnd,
    /// The begin `(?<=\s|^)(\[)(?=[^"#']+?][]}\s]*=)`.
    DestructuredArray,
    /// The end `]`.
    DestructuredArrayEnd,
    /// The match `\b(?<!\.|::)(true|on|yes)(?!\s*[:=][^=])\b`.
    True,
    /// The match `\b(?<!\.|::)(false|off|no)(?!\s*[:=][^=])\b`.
    False,
    /// The match `\b(?<!\.|::)null(?!\s*[:=][^=])\b`.
    Null,
    /// The match `\b(?<!\.|::)extends(?!\s*[:=])\b`.
    Extends,
    /// The match `(?<!\.)\b(?<!\$)(super)(?!\s*[:=][^=]|\$)\b`.
    Super,
    /// The match `(?<!\.)\b(?<!\$)(this)(?!\s*[:=][^=]|\$)\b`.
    This,
    /// The match `(?<!\.)\b(?<!\$)(arguments)(?!\s*[:=][^=]|\$)\b`.
    Arguments,
    /// The match `…`.
    ClassExtends,
    /// The match `…`.
    Class,
    /// The match `\b(debugger|\\)\b`.
    Debugger,
    /// The match `…`.
    SupportClass,
    /// The match `\b(console)\b`.
    Console,
    /// The match `…`.
    ConsoleMethod,
    /// The match `…`.
    ArrayMethod,
    /// The match `((?<=Array\.)(isArray))\b`.
    ArrayStatic,
    /// The match `…`.
    ObjectStatic,
    /// The match `…`.
    MathStatic,
    /// The match `((?<=Number\.)(is(Finite|Integer|NaN)|toInteger))\b`.
    NumberStatic,
    /// The match `…`.
    SupportVariable,
    /// The match `\b(Infinity|NaN|undefined)\b`.
    LanguageConstant,
    /// The match `(?:([$A-Z_a-z][$\w]*)?\s+|(?<![$\w]))(and=|or=)`.
    WordAssignment,
    /// The match `([$A-Z_a-z][$\w]*)?\s*((?:[-%*+]|&&|\|\||\?|(?<!\()/)=)`.
    CompoundAssignment,
    /// The match `([$A-Z_a-z][$\w]*)?\s*((?:[\&^]|<<|>>>??|\|)=)`.
    BitwiseAssignment,
    /// The match `<<|>>>?`.
    Shift,
    /// The match `!=|<=|>=|==|[<>]`.
    Comparison,
    /// The match `&&|!|\|\|`.
    Logical,
    /// The match `[\&^|~]`.
    Bitwise,
    /// The match `([$A-Z_a-z][$\w]*)?\s*(=|:(?!:))(?![=>])`.
    Assignment,
    /// The match `--`.
    Decrement,
    /// The match `\+\+`.
    Increment,
    /// The match `\.\.\.`.
    Splat,
    /// The match `\?`.
    Existential,
    /// The match `[-%*+/]`.
    Arithmetic,
    /// The match `\b(?<![$.])(?:(and|or|not)|(is(?:|nt)))(?!\s*:)\b`.
    WordOperator,
    /// The match `…`.
    EventHandler,
    /// The match `…`.
    SupportMethod,
    /// The match `…`.
    DomMethod,
    /// The match `[$A-Z_a-z][$\w]*`.
    MethodName,
    /// The match `\d[$\w]*`.
    InvalidMethodName,
    /// The begin `(?:(\.)|(::))\s*([$\w]+)\s*(?=\()`.
    MethodCall,
    /// The end `(?<=\))`.
    MethodCallEnd,
    /// The begin `\(`.
    ParenArguments,
    /// The end `\)`.
    ParenArgumentsEnd,
    /// The begin `…`.
    BareMethodCall,
    /// The end `…`.
    BareMethodCallEnd,
    /// The begin `(?=(@|@?[$\w]+|[-=]>|-\d|["'\[{]))`.
    BareArguments,
    /// The end `…`.
    BareArgumentsEnd,
    /// The match `…`.
    SupportFunction,
    /// The match `[$A-Z_a-z][$\w]*`.
    FunctionName,
    /// The match `\d[$\w]*`.
    InvalidFunctionName,
    /// The begin `(@)?([$\w]+)(?=\()`.
    FunctionCall,
    /// The end `(?<=\))`.
    FunctionCallEnd,
    /// The begin `…`.
    BareFunctionCall,
    /// The end `…`.
    BareFunctionCallEnd,
    /// The match `\b(?<!\$)0([Xx])\h+\b(?!\$)`.
    Hex,
    /// The match `\b(?<!\$)0([Bb])[01]+\b(?!\$)`.
    Binary,
    /// The match `\b(?<!\$)0([Oo])?[0-7]+\b(?!\$)`.
    Octal,
    /// The match `…`.
    Decimal,
    /// The match `[A-Z][$0-9A-Z_]*(?=\s*\??(\.\s*[$A-Z_a-z]\w*|::))`.
    ConstantObject,
    /// The match `[$A-Z_a-z][$\w]*(?=\s*\??(\.\s*[$A-Z_a-z]\w*|::))`.
    VariableObject,
    /// The match `…`.
    ConstantObjectProperty,
    /// The match `…`.
    VariableObjectProperty,
    /// The match `(?:(\.)|(::))\s*([A-Z][$0-9A-Z_]*\b\$*)`.
    ConstantProperty,
    /// The match `(?:(\.)|(::))\s*(\$*[$A-Z_a-z][$\w]*)`.
    VariableProperty,
    /// The match `(?:(\.)|(::))\s*([0-9][$\w]*)`.
    InvalidProperty,
    /// The match `::`.
    Prototype,
    /// The match `(?<!\$)\b[0-9]+[$\w]*`.
    InvalidIdentifier,
    /// The match `;`.
    Terminator,
    /// The match `,`.
    Delimiter,
    /// The begin `\{`.
    Brace,
    /// The end `}`.
    BraceEnd,
    /// The begin `\[`.
    Bracket,
    /// The end `]`.
    BracketEnd,
    /// The match `(?<!\.)\.{3}`.
    SliceExclusive,
    /// The match `(?<!\.)\.{2}`.
    SliceInclusive,
    /// The begin `\(`.
    Paren,
    /// The end `\)`.
    ParenEnd,
    /// The match `(@)([$A-Z_a-z]\w*)?`.
    InstanceVariable,
    /// The begin `'`.
    SingleString,
    /// The end `'`.
    SingleStringEnd,
    /// The match `…`.
    SingleEscape,
    /// The match `[$A-Z_a-z]\w*`.
    DestructuredArrayName,
    /// The match `[$A-Z_a-z]\w*`.
    DestructuredObjectName,
    /// The begin `\{`.
    JsxExpression,
    /// The end `}`.
    JsxExpressionEnd,
    /// The match `(?<!["$'./_[:alnum:]])\$(?=[_[:alpha:]][$_[:alnum:]]*)`.
    SvelteVariable,
    /// The match `(?<!["$'./_[:alnum:]])(\$\$)(?=props|restProps|slots)`.
    SvelteProps,
}

